267: /* Returns the sqlite3_value for the given arg of the given function.
268:  * If 0 is returned, an exception has been thrown to report the reason. */
269: static sqlite3_value * tovalue(JNIEnv *env, jobject function, jint arg)
270: {
271:     jlong value_pntr = 0;
272:     jint numArgs = 0;
273: 
274:     // check we have any business being here
275:     if (arg  < 0) { throwex_msg(env, "negative arg out of range"); return 0; }
276:     if (!function) { throwex_msg(env, "inconsistent function"); return 0; }
277: 
278:     value_pntr = (*env)->GetLongField(env, function, func_value);
279:     numArgs = (*env)->GetIntField(env, function, func_args);
280: 
281:     if (value_pntr == 0) { throwex_msg(env, "no current value"); return 0; }
282:     if (arg >= numArgs) { throwex_msg(env, "arg out of range"); return 0; }
283: 
284:     return ((sqlite3_value**)toref(value_pntr))[arg];
285: }
