287: /* called if an exception occurred processing xFunc */
288: static void xFunc_error(sqlite3_context *context, JNIEnv *env)
289: {
290:     jstring msg = 0;
291:     char *msg_bytes;
292:     int msg_nbytes;
293: 
294:     jthrowable ex = (*env)->ExceptionOccurred(env);
295: 
296:     (*env)->ExceptionClear(env);
297: 
298:     msg = (jstring)(*env)->CallObjectMethod(env, ex, exp_msg);
299:     if (!msg) { sqlite3_result_error(context, "unknown error", 13); return; }
300: 
301:     stringToUtf8Bytes(env, msg, &msg_bytes, &msg_nbytes);
302:     if (!msg_bytes) { sqlite3_result_error_nomem(context); return; }
303: 
304:     sqlite3_result_error(context, msg_bytes, msg_nbytes);
305:     freeUtf8Bytes(msg_bytes);
306: }
