308: /* used to call xFunc, xStep and xFinal */
309: static void xCall(
310:     sqlite3_context *context,
311:     int args,
312:     sqlite3_value** value,
313:     jobject func,
314:     jmethodID method)
315: {
316:     JNIEnv *env = 0;
317:     struct UDFData *udf = 0;
318: 
319:     udf = (struct UDFData*)sqlite3_user_data(context);
320:     assert(udf);
321:     (*udf->vm)->AttachCurrentThread(udf->vm, (void **)&env, 0);
322:     if (!func) func = udf->func;
323: 
324:     (*env)->SetLongField(env, func, func_context, fromref(context));
325:     (*env)->SetLongField(env, func, func_value, value ? fromref(value) : 0);
326:     (*env)->SetIntField(env, func, func_args, args);
327: 
328:     (*env)->CallVoidMethod(env, func, method);
329: 
330:     // check if xFunc threw an Exception
331:     if ((*env)->ExceptionCheck(env)) {
332:         xFunc_error(context, env);
333:     }
334: 
335:     (*env)->SetLongField(env, func, func_context, 0);
336:     (*env)->SetLongField(env, func, func_value, 0);
337:     (*env)->SetIntField(env, func, func_args, 0);
338: }
