349: static jobject* get_initialized_udf_context(sqlite3_context *context) {
350:     // clone the Function.Aggregate instance and store a pointer
351:     // in SQLite's aggregate_context (clean up in xFinal)
352:     jobject *func = sqlite3_aggregate_context(context, sizeof(jobject));
353:     if (!*func) {
354:         JNIEnv *env;
355:         struct UDFData *udf = (struct UDFData*)sqlite3_user_data(context);
356:         (*udf->vm)->AttachCurrentThread(udf->vm, (void **)&env, 0);
357: 
358:         *func = (*env)->CallObjectMethod(env, udf->func, aclone);
359:         *func = (*env)->NewGlobalRef(env, *func);
360:     }
361:     return func;
362: }
