410:     // func may not have been allocated if xStep never ran
411:     jobject *func = get_initialized_udf_context(context);
412:     xCall(context, 0, 0, *func, mth_aggr_xfinal);
413: 
414:     // clean up Function.Aggregate instance
415:     (*env)->DeleteGlobalRef(env, *func);
