418: int xCompare(void* context, int len1, const void* str1, int len2, const void* str2)
419: {
420:     JNIEnv *env;
421:     struct CollationData *coll = (struct CollationData*)context;
422:     (*coll->vm)->AttachCurrentThread(coll->vm, (void **)&env, 0);
423: 
424:     // According to https://bugs.openjdk.java.net/browse/JDK-8163861 the len param of NewString
425:     // expects a length in terms of code unit. Being UTF-16, code unit is 16 bits
426:     // SQLite pass the length in bytes for len1 and len2, which is 8 bits
427:     jstring jstr1 = (*env)->NewString(env, str1, len1 / 2);
428:     jstring jstr2 = (*env)->NewString(env, str2, len2 / 2);
429: 
430:     return (*env)->CallIntMethod(env, coll->func, mth_compare, jstr1, jstr2);
431: }
